#!/usr/bin/env python3
"""Full Spanish per-passage gist for The Night Market. Merges into content/gist/the-night-market/es.json
(keeps existing entries, adds the rest). Native review: complete."""
import json, os
OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "content", "gist", "the-night-market", "es.json")
G = {
 2: "Levantas la persiana, enciendes los quemadores bajo la gran olla, cuelgas los dos faroles rojos y limpias el mostrador. En el estante del fondo, un sitio queda vacío. A tu alrededor el mercado despierta: voces, humo, olor a aceite caliente y ajo.",
 3: "Llamas a la Tía. Su voz está cansada pero clara: «Prueba el caldo antes de venderlo. Compra al viejo Han, no a la furgoneta barata. Y aparta un cuenco para el señor Behn.» Cuelga, dolorida, antes de que puedas preguntar más.",
 4: "En la caja hay una tarjeta con la letra de la Tía: la cantidad que debes reunir antes del alba. Es una cifra grande, y un cuenco solo da unas monedas: hará falta una noche entera y bien llena para llegar.",
 5: "La mujer del té del puesto 25, allí desde hace años, se inclina con amabilidad: «Así que eres tú esta noche. La mano de tu tía, ¿es grave?» Ve tu mostrador vacío y tus manos nerviosas, y sonríe: «No te agobies. Te echaré un ojo.»",
 7: "Preguntas quién es el señor Behn. Un silencio. «Un viejo amigo —dice al fin la Tía—. Venía cada noche, y luego dejó de venir. Solo guárdale su cuenco. Por favor.» Hay algo en su voz que no sabes leer.",
 8: "Haces la cuenta: un cuenco vale unas monedas, y la cantidad exigirá cientos — toda una noche sin pausa, sin desperdiciar nada. Se puede; la Tía lo hace cada temporada. Pero ella es rápida y segura, y tú aún no.",
 9: "La mujer del té te explica la noche: «Lleno hacia las nueve, lleno otra vez a medianoche. Precio justo, sé rápida, no desperdicies nada.» Luego, más bajo: «Pasará el señor Sould. Ofrecerá ayuda — un préstamo, una palabra a un rival. Di que no. Su ayuda es un anzuelo.»",
 10: "El cerdo del viejo Han está rosado y fresco, sus verduras crujientes. Lo guardas en la nevera. Costó más de lo que querías — pero la diferencia se notará, y los clientes la sentirán. La buena comida es como la Tía ha sostenido esta esquina treinta años.",
 11: "El género barato cuesta la mitad, así que lo llevas al puesto. Pero el cerdo huele raro y las verduras ya se ablandan. Ahorraste — quizá por el lado equivocado. Un mal cuenco sale caro: un cliente perdido, y todos a quienes se lo cuente.",
 12: "Compras algo bueno y algo barato, para cubrirte. Parece lo prudente. Pero la mitad de tus cuencos no llegarán a lo mejor de la Tía, y un solo cuenco flojo, en mal momento, puede ahuyentar a una multitud. Tendrás que vigilar qué género va en qué cuenco.",
 14: "Le das las gracias. «En esta esquina nos cuidamos —dice—. Tu tía lo ha hecho por mí más veces de las que puedo contar.» Saber que no estás sola esta noche reconforta: una cara amiga vale mucho cuando llega la multitud.",
 15: "Un hombre de abrigo limpio se detiene, sonriendo como un viejo amigo: «Debes de ser la familia de Sim. Qué mala suerte, su mano. No te preocupes — yo cuido de este mercado. Lo que necesites esta noche, ven al señor Sould.» Su sonrisa es cálida. Sus ojos, no.",
 16: "El puesto está listo por fin: faroles rojos, caldo humeante, cuencos apilados. En la galería la multitud ya fluye, densa, entre humo, ruido y el olor de cien cocinas. Algunos tienen hambre. Algunos pararán aquí — si eres rápida y la comida es buena.",
 17: "Tiras lo peor del género barato. Duele tirar dinero ya gastado — pero un mal cuenco costaría mucho más. Guardas lo que aún parece y huele bien, y el resto se va. Mejor una noche más corta que un nombre manchado. La Tía habría hecho lo mismo.",
 18: "Un cuenco espera ahora en el estante del fondo, lleno y caliente, para un hombre que quizá nunca venga. Se ve pequeño ahí arriba, un poco triste — pero también correcto. Es el puesto de la Tía, y así ha sido siempre. Esta noche mantienes vivo algo más que un negocio.",
 19: "El quemador grande chasquea y chasquea sin prender — el gas silba, sin llama. Sin él, el caldo sigue frío, y el caldo frío no vende nada. Te tiemblan un poco las manos; no es el comienzo que querías. Pero todo cocinero ha luchado alguna vez con un quemador terco.",
 20: "Pruebas el caldo: primero la sal, luego el jengibre, luego una nota cálida y honda que no sabes nombrar. Es el sabor por el que se cruza el mercado — treinta años de cuidado en una cucharada. Hazlo como ella te enseñó, y el caldo venderá por ti.",
 21: "La Tía vuelve una y otra vez a la cantidad: «No pierdas la esquina. Mi madre la tuvo antes que yo — treinta años.» El miedo corre bajo sus palabras. La tranquilizas, sin estar segura tú misma. Pero ella debe descansar la mano, y preocuparse al teléfono no ayuda a ninguna.",
 22: "Los clientes de siempre conocen el cuenco de la Tía de memoria — el tamaño, el calor, el precio, el equilibrio exacto. Si el tuyo difiere, lo notarán al primer sorbo. No puedes ser la Tía esta noche. Pero puedes hacer su cuenco a su manera y dejar que hable por ella.",
 23: "Tu primer gran pedido: una familia de seis, hablando todos a la vez. Seis cuencos, con cambios para los niños. Mucho que retener en tu primera hora. Bien hecho, volverán toda la temporada; mal hecho, tu primera historia de la noche será mala.",
 24: "Un niño pequeño cuenta sus monedas en una pila cuidada. Le falta una para un cuenco. Te mira, luego las monedas, luego a ti, sin decir nada. Un instante mínimo — pero cómo respondes es justo lo que un mercado recuerda de un puesto.",
 26: "Los pedidos te llegan por todas partes: «¡Dos cuencos!» «¡Más empanadillas!» «¿Cuánto hay que esperar?» No puedes retenerlos todos. Necesitas un sistema, ya: tomarlos por orden, repetir cada uno, mantener la fila avanzando. El pánico pierde cuencos, la calma los guarda. Eliges la calma.",
 27: "«¿Dónde está Sim?» pregunta un cliente, buscando su cara. «¿Está bien?» Puedes decir la verdad — su mano, la quemadura, tú esta noche — o sonreír, servir, llevarlo liviano. Vienen por la comida, pero también por ella. Tu respuesta dice qué puesto es esta noche.",
 28: "El caldo hirviendo te salpica la mano y ahogas un grito. Quema, agudo y súbito — igual que se lastimó la Tía, piensas sin querer. Un instante, el dolor lo llena todo. Luego respiras y lo envuelves en un paño mojado. El puesto no para por una quemadura.",
 29: "La vaporera silba y calla — seca, las empanadillas a medio hacer. La salvas por los pelos: un minuto más y se queman, y el olor a quemado vacía un mostrador más rápido que nada. La rellenas rápido y con cuidado. Una pequeña victoria — pero suman.",
 30: "Un rato más tranquilo. Limpias, repones cuencos, ordenas el mostrador. En la calma, la mente se va — a la cantidad, al taburete vacío, a la voz preocupada de la Tía. Luego aparece un cliente y vuelves a ello. Pero en las pausas se piensa, y pensar es como se aguanta una noche entera.",
 31: "Llegan los primeros clientes de verdad, hambrientos y listos para pagar. Entonces, ¿qué precio? La Tía tiene uno justo y estable, que todos sus clientes conocen. Puedes igualarlo, subir para los turistas, o bajarlo para vender más. La cifra que elijas esta noche es una especie de promesa.",
 32: "Pones un precio justo — ni alto ni bajo. Es honesto, y lo honesto es fácil de defender. Los clientes pagan sin rechistar; nadie discute lo justo. No ganarás lo máximo por cuenco, pero la gente vuelve, y un puesto lleno siempre vale más que uno avaricioso.",
 33: "Inflas el precio. Los turistas no notarán la diferencia, y más por cuenco significa menos cuencos para llegar a la cantidad — tentador. Pero la voz corre: si los habituales te pillan cobrando el doble, se sentirán estafados, y un puesto que engaña no sostiene una esquina treinta años.",
 34: "Cobras el precio de siempre de la Tía, al céntimo. El primer cliente habitual lo nota, y algo se le afloja en la cara: «Como siempre», dice, contento. Les dice, a su manera, que ella sigue ahí. A veces la opción más segura es también, sin más, la correcta.",
 35: "Sirves el caldo, echas las empanadillas y pasas los primeros cuencos. El vapor sube a la noche fría; unas manos toman los cuencos; las monedas caen en la caja. Funciona — lo estás haciendo de verdad. Y por un momento, sobre todo el ruido, sientes una pequeña y feroz chispa de orgullo.",
 36: "Alguien refunfuña, fuerte, que es muy caro. Giran unas cabezas. Un refunfuño puede extenderse por la fila o morir en el sitio, según lo que hagas. Puedes volver al precio justo y guardar la paz, o mantenerte firme y confiar en que la comida hable más fuerte que una voz.",
 37: "Un cliente da un bocado y se detiene en seco: «Es el de verdad —dice, sorprendido—. Como el suyo.» Lo dice lo bastante fuerte para que oigan, y algunos se acercan. La buena comida es su mejor anuncio — una boca contenta arrastra una cola entera.",
 38: "Un cliente frunce el ceño: «Está algo soso. No como de costumbre.» Quizá el género barato, quizá tu mano con el jengibre. Duele oírlo la primera noche. Puedes corregir el sazón ahora, antes del próximo cuenco, o dejarlo y confiar en que la multitud lo tape.",
 39: "Entre pedidos, miras de reojo la caja. Ya hay monedas dentro — de verdad, ganadas con tus manos. Lejísimos de la cantidad, aún, pero es un comienzo, y un comienzo vale mucho más que nada hace una hora. Cierras la tapa y vuelves al vapor y la multitud.",
 40: "Cuentas rápido, bajo el mostrador. Es un comienzo — pero solo eso. A este ritmo no llegarás a la cantidad al alba; necesitas el apogeo, y que sea bueno. La gran multitud de medianoche, hambrienta y pronta a gastar, es lo que hace o deshace una noche así.",
 41: "Y entonces llega la multitud — ya no un hilo sino una ola. Oficinistas, familias, trabajadores del turno de noche, volcándose de golpe en la galería, y el ruido se duplica. Diez caras en tu mostrador, luego veinte. Los pedidos vuelan. Es el apogeo. Es la noche. Ahí viene.",
 43: "La galería está abarrotada, la gente empuja con bolsas y niños dormidos. El aire es denso y caliente de vapor y aceite. Tu puestito es una isla en el ruido. Ya no hay tiempo de pensar, solo de moverse — así que respiras hondo y te metes.",
 45: "Vas demasiado rápido. Un cuenco sale a medio hacer; das de menos en el cambio, por descuido o no. Te dices que es el apogeo, que todos lo hacen. Pero recortar es un agujero en el cubo — te desagua el buen nombre, un cortecito cada vez, hasta que no queda.",
 46: "Pides ayuda, la voz quebrándose sobre el ruido. ¿Pero quién puede venir? El chaval del mercado está cerca — rápido, siempre hambriento, siempre listo para un recado por una moneda. O la mujer del té de al lado, aunque un vistazo basta: está tan desbordada como tú. Un segundo para elegir.",
 47: "El apogeo sigue y sigue. Te duelen los brazos, la espalda — pero la caja pesa más, y ese sonido, monedas sobre monedas, te mantiene. Cuenco tras cuenco, cara tras cara. Estás metida de lleno, y aguantas. No creías que pudieras. Y aquí estás.",
 48: "«Oye — esto no cuadra.» El cliente tiende la mano, la palma abierta: el cambio está corto. Giran unas cabezas. Se te calienta la cara. Es el momento: puedes disculparte y arreglarlo al instante, o discutir y esperar que ceda antes de que oigan más.",
 49: "Miras el género y se te cae el alma: el cerdo casi agotado, las verduras a un último puñado. La noche no va ni por la mitad y ya te quedas sin nada. Puedes hacer cuencos más pequeños para estirar, mandar por más, o dejar que la vaporera se seque y decida por ti.",
 50: "Por un momento la multitud afloja y respiras. Te secas el sudor y el mostrador. Los faroles se mecen con el viento. No durará — el verdadero apogeo de medianoche aún llega — pero una calma es un regalo. Úsala bien, y prepárate para cuando vuelva la ola.",
 51: "«Tienes razón — perdona.» Vuelves a contar, despacio esta vez, y pones la moneda que faltaba en su mano. «Noche larga. Gracias por la paciencia.» El cliente se ablanda; las cabezas se giran. Un error arreglado rápido y con tino no es una mancha — bien llevado, hasta cuenta algo a tu favor.",
 52: "Te apoyas en el mostrador y respiras un segundo. La caja pesa ya — más de lo que osabas esperar hace una hora. Podrías parar a contarla, para ver cuánto te falta para la cantidad. O dejar la cuenta para luego y volver mientras la multitud está aquí y gasta.",
 54: "«El cambio estaba bien», dices, sosteniéndole la mirada hasta que la aparta. Se encoge de hombros y se va rezongando. Ganaste — salvo que no. Lo contará, y en un mercado un nombre corre más que un cliente. Salvaste una moneda esta noche, y gastaste algo mucho más valioso.",
 55: "Pones monedas en la mano del chaval y lo mandas por más cerdo y verduras. Conoce cada callejón y se va antes de que acabes la frase. Ahora debes llevar el puesto sola hasta que vuelva. Esperas que el género aguante, y que el chaval sea tan rápido y honrado como crees.",
 56: "Haces los cuencos algo más pequeños — más caldo, menos empanadillas, un poco menos de cerdo. Pocos lo notarán una noche tan llena. Estira el género y gana tiempo. No es engañar; el cuenco sigue bueno, honrado y caliente. Solo una cocinera cuidando lo que tiene — la Tía asentiría.",
 57: "El apogeo sigue y pierdes la noción del tiempo dentro de él. Solo vapor, caras, cuencos, monedas, y el calor de los quemadores en los brazos. Ahí fuera se hace tarde; en algún sitio la cantidad aún espera. Pero ahora solo existe el próximo cuenco, y el siguiente, y el siguiente.",
 59: "En un hueco, tu ojo cae en el estante del fondo. El cuenco apartado se enfría despacio. Debajo, el taburete del extremo sigue vacío, como toda la noche — el del señor Behn. ¿Quién es? ¿Por qué la Tía le guarda el cuenco? El apogeo tira, pero el taburete vacío también, más callado.",
 60: "Al fin el apogeo culmina y rompe. La multitud pasa de ola a hilo, y alzas la vista, parpadeando, como quien emerge de aguas hondas. Sigues en pie; el puesto sigue siendo tuyo. Pero la noche no ha acabado contigo — siempre llega algo en la calma tras la ola.",
 63: "«No, gracias —dices—. Nos las arreglaremos.» La sonrisa de Sould se sostiene, pero sus ojos se enfrían un grado. «Como quieras», y pasa al puesto siguiente. Te sientes más ligera en cuanto se va. Pase lo que pase esta noche, será tuyo — la victoria o la pérdida, pero sin su anzuelo en ti.",
 64: "Tomas el dinero de Sould. La cantidad está cubierta, haga lo que haga la noche. Un instante el peso se va y respiras. Luego sube el desasosiego. No leíste ninguna condición; no sabes qué significa «luego». Cambiaste una preocupación por otra — y esta sonríe, y sabe dónde encontrarte.",
 65: "«¿Cuánto cuesta?» preguntas. Sould sonríe más: «No te preocupes por eso ahora. Ya lo arreglaremos luego. Entre amigos, siempre.» No da una cifra, y ahí está toda la trampa. Un precio real se sopesa; un precio sin cifra es una cuerda sin cabo. Ahora lo ves claro.",
 66: "Miras la fila de puesteros esperando para pagar a Sould. Algunos parecen tranquilos; otros, cansados y un poco asustados. Una anciana cuenta sus monedas dos veces antes de dárselas. Así funciona de verdad el mercado, bajo los faroles: un hombre callado, una larga fila, y el dinero yendo hacia él toda la noche.",
 67: "La puestera de al lado se inclina: «Ofrezca lo que ofrezca, di que no —murmura—. Sould nunca olvida una deuda. Mi primo pidió una vez. Tres años pagándola. Tres años.» Se endereza cuando Sould mira. «Solo... ten cuidado», dice, y vuelve a su puesto. El aviso se te queda frío en el pecho.",
 68: "Cerca del cierre, Sould vuelve a acercarse. «¿Ya llegaste a la cantidad? —pregunta, suave, como si le importara—. Porque la oferta sigue en pie. Última oportunidad esta noche.» Sabe exactamente cómo te ha ido la noche — siempre lo sabe. Su préstamo acabaría el miedo ya. Pero su préstamo nunca acaba de verdad.",
 74: "Le das al chaval un cuenco lleno: «Come. Te lo ganaste.» Se le transforma toda la cara. Come rápido, en un rincón, como si temiera que desapareciera. Es un cuenco; casi no te cuesta nada. Pero para el chaval es el mundo entero un instante — y no olvidará quién se lo dio.",
 75: "Pagas al chaval en monedas, como acordaste, nada más. Se las guarda y asiente — lo entiende; las monedas son el trato, y el trato es justo. Pero sigue con hambre, y mira los cuencos al irse. Fuiste justa. Justa está bien. Pero justa no es del todo lo mismo que amable.",
 76: "El chaval no se va. Ronda el borde del puesto — mira, aprende, alcanza un paño o una cuchara antes de que lo pidas. Tenerlo cerca aligera toda la noche. Un mercado está lleno de gente que se cuela por las grietas, y a veces un puesto es el único sitio cálido que los deja quedarse.",
 77: "Entre cuencos, el chaval te dice su nombre. Y dónde duerme — un rincón seco tras el arco del pescado, casi siempre. Lo dice sin más, sin buscar lástima. Escuchas, y lo recuerdas. Un nombre es poco para dar y mucho para guardar, y el mercado parece un poco menos de extraños.",
 78: "Dejas al chaval cuidando el puesto mientras sales atrás por más género. Una pequeña confianza, que él toma en serio — firme, haciendo esperar a los clientes, guardando la caja con los dos ojos. Al volver, no falta nada. Confianza dada, confianza cumplida — y eso importa, en un sitio así.",
 79: "La lluvia barre la galería, súbita y dura, tamborileando en los techos. La multitud se dispersa a cubierto, y tu mostrador se vacía en segundos. La lluvia puede matar una noche de ventas. O, bien llevada, llenar tu puesto de gente mojada que de pronto quiere algo caliente. Depende de ti.",
 80: "Revisas las ollas. El caldo está bajo, el género casi agotado — da para un rato, no para toda la noche. Ahora debes elegir cómo gastar lo que queda. Cuencos pequeños y cuidados, para estirar hasta el alba. O cuencos llenos y generosos ahora, y arriesgarte a secarte horas antes de tiempo.",
 81: "Bajas el toldo y aguantas. La lluvia cae en una larga línea de plata. Un rato casi no viene nadie, así que aprovechas — limpiar, reponer, descansar los pies, probar el caldo. La lluvia siempre pasa al final. Y entonces el mercado vuelve a salir, frío y hambriento, y estarás lista y caliente.",
 82: "Gritas a la lluvia: «¡Cuencos calientes! ¡Salid de lo mojado!» Unos cuantos empapados se meten bajo el toldo, agradecidos. Les vendes cuencos más pequeños, más baratos, rápidos y calientes. Menos dinero por cuenco. Pero un puesto lleno atrae más que uno vacío, y el calor se vende solo en una noche fría y húmeda.",
 83: "La olla grande está casi vacía — se ve el fondo bajo el último caldo. Este es el verdadero punto de peligro de la noche. Secarte muy pronto, y te quedas ante un puesto frío y cerrado mientras el mercado sigue en marcha. Puedes estirar lo último, o aceptar que la olla acabó y contar lo hecho.",
 84: "Estiras el último caldo — un poco más de agua, mano prudente con la especia, cuencos pequeños a precios pequeños. Es más claro que lo mejor de la Tía, lo sabes. Pero sigue caliente, honrado, y suyo en la forma. Mejor un cuenco pequeño de verdad que ninguno — así que mantienes el farol y la olla un rato más.",
 85: "La noche gira ya. La multitud afloja, el ruido se suaviza, y el mercado empieza su lento deslizarse hacia el alba. Puestos más allá recogen ya sus persianas. Pronto pasará el maestro por las cuotas. Sientes toda la larga noche en los brazos y la espalda — pero casi acaba, y casi lo lograste, de un modo u otro.",
 86: "Un puesto nuevo abre justo enfrente, a mitad de tu precio. El dueño grita fuerte, llama a la gente, y parte de tu cola se va con él. Barato y ruidoso arrastra multitud rápido en una noche así. Puedes bajar para igualarlo y pelear — o mantener el precio, y confiar en que tu comida retenga a tu gente.",
 87: "Bajas para igualarlo, y ya estás en una guerra de precios. Los cuencos vuelan, pero cada uno casi no deja nada. Desbordada, no avanzas. Es una carrera al fondo, y el fondo es donde los puestos cierran para siempre. No se gana una noche solo con el precio — necesitas otra vía, y rápido.",
 88: "Dejas tu mostrador y vas derecha a ella. Juntas enderezáis el perol, secáis el té caliente, calmáis a sus clientes molestos y la ponéis en marcha otra vez. Te cuesta unos minutos y unas ventas. Te agarra del brazo, sin aliento: «No lo olvidaré.» Y en esta esquina, eso no son solo palabras.",
 89: "Mantienes tu precio y dejas que el puesto barato se desgañite. Algunos se van con él, sí. Pero tus habituales se quedan. «El suyo es agua —dice uno, señalando tu olla—. El tuyo es el de verdad.» La buena comida es más lenta para ganar una noche, pero más segura. No eres el más barato — eres por el que se hace cola.",
 90: "De madrugada, el puesto barato de enfrente se apaga. Vendió todo demasiado barato, casi no ganó nada, y se quedó sin género y sin ánimo a la vez. El dueño recoge, cansado y agrio. Tu farol sigue encendido, tu olla aún caliente. Lento, constante y honrado dura más que ruidoso y barato, casi siempre.",
 91: "El cierre se acerca. La multitud es escasa, el ruido bajo. En el estante, el cuenco apartado aún espera — frío ya, pero ahí. Debajo, el taburete del extremo sigue vacío. En cualquier momento pasará el maestro. Pero tus ojos vuelven una y otra vez a ese taburete, al cuenco frío, y a la pregunta sin respuesta.",
 92: "Sould aparece en tu mostrador, justo a tiempo: «¿Y bien? ¿Llegaste a la cantidad? ¿O necesitas ese pequeño préstamo, al final?» Si te falta, es la salida fácil: tomar su dinero, pagar al maestro, guardar la esquina esta noche. Pero ya conoces el precio real de su ayuda. Tienes que responderle.",
 93: "Un anciano avanza despacio entre la multitud ralea — delgado, gris, cansado. Se detiene en el taburete vacío del extremo y pone una mano sobre él, como si lo conociera bien. Te mira, luego al estante, luego aparta la vista. No se sienta. No pide. Solo está ahí, esperando algo que no sabes nombrar.",
 94: "Bajas el cuenco apartado y lo pones ante él: «Este es suyo. Siempre lo ha sido.» El anciano mira el cuenco, luego a ti, y se le llenan los ojos. «Lo guardó —dice muy bajo—. Todo este tiempo. Lo guardó.» Aún no lo entiendes del todo — pero sabes que hiciste algo justo.",
 95: "Le sirves, y al fin se sienta. Mientras come, habla un poco. Él y la Tía fueron cercanos, hace tiempo — luego una riña, pequeña y tonta, de las que se endurecen con los años. Dejó de venir. Pero nunca dejó de querer hacerlo. «Dile —susurra—. Dile que Behn ha vuelto.»",
 96: "El taburete del extremo estuvo vacío toda la noche, mientras los demás se llenaban y vaciaban una y otra vez. Un taburete vacío, un cuenco frío apartado en el estante de arriba. Es lo más silencioso de un mercado ruidoso — y, si prestas oído, lo más ruidoso. La Tía lo guarda por algo. Ojalá supieras por qué.",
 97: "Piensas en la cara de la Tía al teléfono — cómo le cambió la voz con el nombre de Behn. No rabia. Algo más suave y más triste. Quienquiera que sea, aún le importa, tras todos estos años. El cuenco del estante no es solo una costumbre. Es una puerta que ella deja abierta, por si acaso. Eso ya lo entiendes.",
 98: "Junto a la caja, medio escondida, hay una vieja foto. Has pasado toda la noche sin mirarla. Ahora sí: la Tía, mucho más joven, riendo. A su lado, un joven que también ríe. Al dorso, de su letra, dos palabras: yo y Behn. El taburete vacío y el cuenco frío cobran de pronto un sentido.",
 100: "Mientras Behn come, empiezas a entender en qué se ha convertido de verdad esta noche. Nunca fue solo por la cantidad. La Tía te mandó a llevar el puesto — pero también, sin decirlo, a mantener su puerta abierta. Y funcionó: él volvió. Pase lo que pase con el dinero, esta parte de la noche ya es una victoria.",
 101: "Hora de cerrar. Sacas la caja y cuentas, moneda a moneda, a la luz baja de los faroles. El corazón late fuerte. ¿Es suficiente? La cifra sube según cuentas, y vuelves a contar para asegurarte. Por la fila oyes venir al maestro — de puesto en puesto, cobrando las cuotas, una puerta tras otra. Tu turno está cerca.",
 102: "El maestro baja por la fila, lento y seguro. Viejo, justo, ha visto en treinta años toda treta de un puesto. En cada sitio para, cobra la cuota, apunta en su libro, sigue. Algunos pagan sin problema; otros no pueden. Lo miras acercarse y aprietas un poco más tu caja.",
 103: "Ves a un puesto más allá quedarse corto. El maestro niega con la cabeza, firme pero sin dureza. El puestero empieza, despacio, a recoger — platos, ollas, toda una vida de noches, guardada en cajas. Sin gritos, solo un final tranquilo. Podrías ser tú en una hora. La idea te da acero: esta noche no, la esquina de la Tía no.",
 104: "Uno a uno, por toda la fila, bajan los faroles. El mercado se va a dormir. El mundo vivo y ruidoso de hace unas horas se pliega en cajas y sombras. Tus dos faroles rojos aún brillan, por ahora. Que cuelguen aquí la próxima temporada se juega en los próximos minutos — y en las monedas de tu caja.",
 105: "Una luz gris trepa por los techos del mercado: el alba, el fin de la noche y el fin de la temporada. En algún sitio un pájaro solitario arranca. El aire huele a ceniza fría y vapor viejo. Has estado en pie toda la noche, y sientes cada hora. Pero sigues aquí, y el puesto sigue siendo tuyo — por ahora.",
 110: "El maestro para en el puesto 24. Te mira, luego al puesto, luego al sitio vacío de la Tía. «Así que eres tú esta noche —dice—. ¿Cómo nos fue?» Esto es: toda la noche reducida a un instante y una cifra. Respiras y abres la caja. Todo lo que hiciste esta noche está ahí dentro.",
 111: "Lo cuentas ante él, moneda a moneda. Toda la noche está en el dinero — los buenos cuencos, las decisiones duras, las esquinas guardadas o recortadas. El maestro mira, paciente, sin decir nada. Estás cerca de la cantidad. Cerca. Pero «cerca» puede caer de cualquier lado al alba, y todo pende de este último recuento.",
 112: "El recuento se queda justo por debajo. Por poco — pero corto es corto, y el libro del maestro no redondea para nadie. La esquina se te escapa, moneda a moneda que falta. A menos que — quizá quede una carta o dos por jugar, si llevaste bien el resto de la noche. Piensas rápido: ¿qué tienes que el dinero solo no muestra?",
 113: "Estás en el último recurso. Falta dinero, el intermediario se negó, la mujer del té ya está al límite. Queda lo más pequeño y callado — una amabilidad hecha antes, quizá, que vuelve. O nada en absoluto. A veces una noche no cuadra, por más que la trabajes. Esperas a ver qué clase de noche resulta ser.",
 114: "No queda nada que oponer a la cuota. Ni dinero bastante, ni favor debido, ni amabilidad que vuelva. Solo tú, una caja fría de monedas, y una cifra que no pudiste alcanzar. El maestro espera tu respuesta, sin crueldad. Acabe como acabe esto, trabajaste toda la noche por ello — y eso tiene que contar, aunque no sea esta noche.",
}
def main():
    data=json.load(open(OUT,encoding="utf-8")); a=0
    for nid,t in G.items():
        k=str(nid)
        if k not in data: data[k]=t; a+=1
    data={k:data[k] for k in sorted(data,key=lambda x:int(x))}
    json.dump(data,open(OUT,"w",encoding="utf-8"),ensure_ascii=False,indent=1)
    print(f"the-night-market/es.json: {len(data)} (+{a})")
if __name__=="__main__": main()
